parameters.jsCode:
const body = $input.item.json.body;
if (!body || !body.data || body.data.length === 0) return [];

const msgData = body.data[0];
const messageType = msgData.messageType;
const fromMe = msgData.key.fromMe;
const phone = msgData.key.remoteJid;

// 1. Hanya proses pesan text yang bukan dari bot sendiri dan bukan dari grup
if (fromMe || phone.includes('@g.us') || (messageType !== 'conversation' && messageType !== 'extendedTextMessage')) return [];

const text = msgData.message?.conversation || msgData.message?.extendedTextMessage?.text || '';

// 2. Format laporan: LAPOR [JENIS] [LOKASI] - [DESKRIPSI]
// Contoh: LAPOR KEBAKARAN Pasar Inpres - Api mulai membesar
if (!text.toUpperCase().startsWith('LAPOR')) return [];

// 3. Parsing sederhana
const parts = text.split(' ');
const type = parts.length > 1 ? parts[1].toUpperCase() : 'LAINNYA';
let description = text.substring(text.indexOf(type) + type.length).trim();
let location = 'Tidak Spesifik';

if (description.includes('-')) {
  const descParts = description.split('-');
  location = descParts[0].trim();
  description = descParts.slice(1).join('-').trim();
}

return [{
  json: {
    phone: phone.replace('@s.whatsapp.net', ''),
    type: type,
    description: description,
    location: location,
    raw_text: text
  }
}];

